CREATE TABLE IF NOT EXISTS state_legal_jurisdictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, state_code text NOT NULL, state_name text NOT NULL, lga_code text, lga_name text, administrative_level text NOT NULL DEFAULT 'State', status text NOT NULL DEFAULT 'Active', source_reference text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_code,state_code,lga_code));
CREATE TABLE IF NOT EXISTS state_legal_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES state_legal_jurisdictions(id) ON DELETE CASCADE, title text NOT NULL, source_type text NOT NULL, issuing_authority text NOT NULL, source_url text NOT NULL, publication_or_effective_date date, verification_status text NOT NULL DEFAULT 'Verified', reliability_score numeric(5,2) NOT NULL DEFAULT 95, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS state_legal_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES state_legal_jurisdictions(id) ON DELETE CASCADE, source_id uuid REFERENCES state_legal_sources(id) ON DELETE SET NULL, rule_code text NOT NULL, domain_code text NOT NULL, rule_title text NOT NULL, rule_statement text NOT NULL, trigger_condition text, mandatory boolean NOT NULL DEFAULT true, confidence_score numeric(5,2) NOT NULL DEFAULT 90, effective_from date, review_status text NOT NULL DEFAULT 'Current-source-reviewed', status text NOT NULL DEFAULT 'Active', UNIQUE(jurisdiction_id,rule_code));
CREATE TABLE IF NOT EXISTS state_authorities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES state_legal_jurisdictions(id) ON DELETE CASCADE, authority_code text NOT NULL, authority_name text NOT NULL, authority_role text NOT NULL, source_id uuid REFERENCES state_legal_sources(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS state_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES state_legal_jurisdictions(id) ON DELETE CASCADE, requirement_code text NOT NULL, domain_code text NOT NULL, requirement_name text NOT NULL, trigger_condition text NOT NULL, required_evidence text NOT NULL, authority_code text, blocking_if_unresolved boolean NOT NULL DEFAULT true, source_id uuid REFERENCES state_legal_sources(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS asset_state_legal_contexts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, jurisdiction_id uuid NOT NULL REFERENCES state_legal_jurisdictions(id) ON DELETE CASCADE, lga_name text, land_status text NOT NULL DEFAULT 'Unassessed', planning_status text NOT NULL DEFAULT 'Unassessed', environmental_status text NOT NULL DEFAULT 'Unassessed', community_rights_status text NOT NULL DEFAULT 'Unassessed', survey_status text NOT NULL DEFAULT 'Unassessed', investment_screening_status text NOT NULL DEFAULT 'Unassessed', blocking_issue_count integer NOT NULL DEFAULT 0, required_action_count integer NOT NULL DEFAULT 0, rationale text, assessed_at timestamptz NOT NULL DEFAULT now(), assessor_reference text, status text NOT NULL DEFAULT 'Draft', UNIQUE(asset_id,jurisdiction_id));
CREATE INDEX IF NOT EXISTS idx_state_juris ON state_legal_jurisdictions(state_code,lga_name);
CREATE INDEX IF NOT EXISTS idx_state_rules ON state_legal_rules(jurisdiction_id,domain_code);
CREATE INDEX IF NOT EXISTS idx_state_reqs ON state_requirements(jurisdiction_id,domain_code);
CREATE INDEX IF NOT EXISTS idx_asset_state_context ON asset_state_legal_contexts(asset_id,assessed_at DESC);